{
  "title": "The Clockwork Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a map of the ruined city at dusk.",
      "visual_description": "Mara stands atop a crumbling wall, unrolling a stained parchment map as the sun sets behind broken towers.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver tests a mirror pool in the courtyard.",
      "visual_description": "In a cracked stone courtyard, the glass diver touches a standing mirror that ripples like water, their helmet reflecting the ruined castle gates.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning about the cursed tower.",
      "visual_description": "Inside a collapsed hall, the oracle lamp sits on a pedestal, its single eye-flame darting toward a distant spire wrapped in thorny vines.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector snores on a pile of stamped papers.",
      "visual_description": "In a dusty archive room, the sleeping tax collector uses a thick ledger as a pillow, papers stuck to their sleeves fluttering slightly.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scouts ahead through the castle gates.",
      "visual_description": "The tin fox creeps through the open rusted castle gates, its key-wind tail ticking softly, blue glass eyes scanning the shadows.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara and the glass diver follow the tin fox's trail.",
      "visual_description": "Mara and the glass diver move quietly through a narrow alley lined with tattered royal banners, following tiny paw prints.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns of a patrol approaching.",
      "visual_description": "The oracle lamp's flame turns blue and pulses rapidly, casting long shadows as armored figures march in the distance.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The sleeping tax collector is prodded awake.",
      "visual_description": "The tin fox nudges the sleeping tax collector's cheek with a cool metal nose, causing them to stir and blink groggily.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara deciphers a riddle on a magic door.",
      "visual_description": "Mara traces glowing runes on a stone door with her ink-stained fingers, her brass compass swinging wildly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver swims through a window into a locked chamber.",
      "visual_description": "The glass diver presses their helmet against a cracked window, then steps through as if diving into water, emerging inside a dusty room.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp illuminates a hidden passage.",
      "visual_description": "The oracle lamp's flame brightens, revealing a narrow stone staircase hidden behind a false wall draped with old banners.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The sleeping tax collector finds a useful key in their papers.",
      "visual_description": "Rummaging through stamped documents, the sleepy official pulls out a rusted brass key that glows faintly.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "Mara uses the key on a cursed tower door.",
      "visual_description": "Mara inserts the glowing key into the lock of a twisted iron door at the base of the cursed tower; the lock clicks.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The team ascends the spiral stairs inside the tower.",
      "visual_description": "The group climbs a narrow spiral staircase, walls covered in faded murals, the oracle lamp casting moving shadows.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver retrieves the trapped person from the top chamber.",
      "visual_description": "In a round chamber at the tower's top, the glass diver reaches through a shimmering mirror to pull a dazed figure free.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The tower begins to collapse as they flee.",
      "visual_description": "Stone blocks tumble from the ceiling as the group rushes down the stairs, the tin fox leading the way.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They escape across a crumbling bridge.",
      "visual_description": "The team races across a stone bridge that cracks and falls behind them, the royal banners below catching fire.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They reach safety as dawn breaks over the ruined city.",
      "visual_description": "Exhausted but safe, the group collapses on a hill as the first light of dawn paints the broken city in gold.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ],
  "gate_token": "_SA4UL0vEQr4gb_W98gGog"
}

